#if UNITY_EDITOR
using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
namespace DeliveryService.Mok.Editor {
[InitializeOnLoad]public static class CityExpansionLife{
static CityExpansionLife(){EditorApplication.update+=Poll;}
static void Poll(){if(EditorApplication.isCompiling||EditorApplication.isUpdating||EditorApplication.isPlayingOrWillChangePlaymode||!File.Exists("Temp/Mok-city-life"))return;File.Delete("Temp/Mok-city-life");try{Run();}catch(Exception e){File.WriteAllText("Temp/Mok-city-life.txt",e.ToString());}}
static void Run(){var scene=SceneManager.GetSceneByPath("Assets/Scenes/JJinCity.unity");bool opened=!scene.isLoaded;if(opened)scene=EditorSceneManager.OpenScene("Assets/Scenes/JJinCity.unity",OpenSceneMode.Additive);var previous=SceneManager.GetActiveScene();SceneManager.SetActiveScene(scene);try{
EditorSceneManager.SaveScene(scene,"Temp/JJinCity-before-city-life.unity",true);var root=scene.GetRootGameObjects().First(g=>g.name=="Mok East City").transform;if(root.Find("Street details")!=null)throw new Exception("Already populated");var details=new GameObject("Street details").transform;details.SetParent(root,false);var paint=AssetDatabase.LoadAssetAtPath<Material>("Assets/Scripts/Mok/Art/EastCity/Road paint.mat");var seam=AssetDatabase.LoadAssetAtPath<Material>("Assets/Scripts/Mok/Art/EastCity/Quay stone.mat");
void Box(string name,Vector3 pos,Vector3 scale,Material m){var g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name=name;g.transform.SetParent(details,false);g.transform.position=pos;g.transform.localScale=scale;g.GetComponent<Renderer>().sharedMaterial=m;UnityEngine.Object.DestroyImmediate(g.GetComponent<Collider>());g.isStatic=true;}
float[] xs={210,290,370,440},zs={-110,-5,100};foreach(float x in xs)foreach(float z in zs)for(int k=-4;k<=4;k+=2){Box("Crosswalk",new Vector3(x+k,.025f,z+8),new Vector3(1,.012f,2.8f),paint);Box("Crosswalk",new Vector3(x+8,.025f,z+k),new Vector3(2.8f,.012f,1),paint);}
// 보도 경계의 타일 줄눈은 작은 높이 차이 없이 시각 요소로만 둔다.
for(int i=0;i<3;i++)for(int j=0;j<2;j++){float l=xs[i]+6,r=xs[i+1]-6,b=zs[j]+6,t=zs[j+1]-6;for(float x=l+2;x<r;x+=2){Box("Pavement seam",new Vector3(x,.055f,b+1.5f),new Vector3(.025f,.006f,3),seam);Box("Pavement seam",new Vector3(x,.055f,t-1.5f),new Vector3(.025f,.006f,3),seam);}for(float z=b+2;z<t;z+=2){Box("Pavement seam",new Vector3(l+1.5f,.055f,z),new Vector3(3,.006f,.025f),seam);Box("Pavement seam",new Vector3(r-1.5f,.055f,z),new Vector3(3,.006f,.025f),seam);}}
var traffic=new GameObject("East traffic routes").transform;traffic.SetParent(root,false);
WayPoint[] Loop(string label,Vector3[] corners){var points=new List<Vector3>();for(int n=0;n<corners.Length;n++){var a=corners[n];var b=corners[(n+1)%corners.Length];int steps=Mathf.CeilToInt(Vector3.Distance(a,b)/35);for(int i=0;i<steps;i++)points.Add(Vector3.Lerp(a,b,i/(float)steps));}var result=points.Select((p,i)=>{var g=new GameObject(label+" "+i);g.transform.SetParent(traffic,false);g.transform.position=p;return g.AddComponent<WayPoint>();}).ToArray();for(int i=0;i<result.Length;i++)result[i].nextWaypoints.Add(result[(i+1)%result.Length]);return result;}
var outer=Loop("Outer lane",new[]{new Vector3(207,.05f,-113),new Vector3(443,.05f,-113),new Vector3(443,.05f,103),new Vector3(207,.05f,103)});
var inner=Loop("Inner lane",new[]{new Vector3(293,.05f,-107),new Vector3(293,.05f,97),new Vector3(367,.05f,97),new Vector3(367,.05f,-107)});
var cars=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<CarMov>()).OrderBy(c=>c.name).ToArray();if(cars.Length!=50)throw new Exception("Expected existing fleet 50, got "+cars.Length);
for(int i=0;i<16;i++){var loop=i<12?outer:inner;int slot=i<12?i:i-12;int n=Mathf.FloorToInt(slot*loop.Length/(i<12?12f:4f));var a=loop[n].transform.position;var target=loop[(n+1)%loop.Length];var car=cars[cars.Length-1-i];car.transform.position=a;car.transform.rotation=Quaternion.LookRotation(target.transform.position-a);var so=new SerializedObject(car);so.FindProperty("currentTarget").objectReferenceValue=target;so.ApplyModifiedPropertiesWithoutUndo();PrefabUtility.RecordPrefabInstancePropertyModifications(car);PrefabUtility.RecordPrefabInstancePropertyModifications(car.transform);}
// 기존 시민 프리팹과 행동을 그대로 사용하고 새 구역 전용 생성 범위만 지정한다.
var original=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<NPCManager>()).First();var citizenRoot=new GameObject("East citizens");citizenRoot.transform.SetParent(root,false);citizenRoot.transform.position=new Vector3(325,0,-5);var manager=citizenRoot.AddComponent<NPCManager>();EditorUtility.CopySerialized(original,manager);var area=citizenRoot.AddComponent<BoxCollider>();area.isTrigger=true;area.size=new Vector3(230,.2f,200);var config=new SerializedObject(manager);config.FindProperty("spawnArea").objectReferenceValue=area;config.FindProperty("npcParent").objectReferenceValue=citizenRoot.transform;config.FindProperty("maxNPCCount").intValue=18;config.ApplyModifiedPropertiesWithoutUndo();
EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);File.WriteAllText("Temp/Mok-city-life.txt","PASS street details; existing fleet remains 50 (34 original district / 16 new district); 18 citizen spawns configured.");
}finally{SceneManager.SetActiveScene(previous);if(opened)EditorSceneManager.CloseScene(scene,true);}}
}}
